#!/usr/bin/env bash
# Creates the lab's secrets once, on this machine only (both are git-ignored):
#   lab.env  - random passwords for MariaDB and Zabbix (format: lab.env.example)
#   pki/     - internal certificate authority + TLS certificate for www.dc.lab (DMZ website)
# Safe to run again: existing files are kept. ("RAM\+": a bare + splits an OpenSSL subject field.) deploy.sh runs it before every deploy.
cd "$(dirname "$0")/.."

if [ ! -f lab.env ]; then
  rnd() { openssl rand -hex 12; }
  cat > lab.env <<ENV
# Generated by scripts/gen-secrets.sh on $(date +%F) - never commit this file.
DB_WEB_PASS=$(rnd)
DB_APP_PASS=$(rnd)
DB_REPL_PASS=$(rnd)
DB_BACKUP_PASS=$(rnd)
ZBX_DB_PASS=$(rnd)
ZBX_ADMIN_PASS=$(rnd)
# Arista cEOS lab login (in configs/ceos/*.cfg, reachable only on the OOB management VRF)
SWITCH_USER=admin
SWITCH_PASS=admin
ENV
  chmod 600 lab.env
  echo "[gen-secrets] lab.env created with random passwords"
fi

if [ ! -f pki/www.crt ]; then
  mkdir -p pki && chmod 700 pki
  openssl req -x509 -newkey rsa:3072 -nodes -days 3650 -subj "/O=RAM\+ Data Center/CN=RAM\+ Lab Root CA" \
    -keyout pki/ca.key -out pki/ca.crt 2>/dev/null
  openssl req -newkey rsa:2048 -nodes -subj "/O=RAM\+ Data Center/CN=www.dc.lab" \
    -keyout pki/www.key -out pki/www.csr 2>/dev/null
  printf 'subjectAltName=DNS:www.dc.lab,DNS:dc.lab,IP:10.10.60.20,IP:10.0.0.1,IP:10.0.0.5\nextendedKeyUsage=serverAuth\n' > pki/www.ext
  openssl x509 -req -in pki/www.csr -CA pki/ca.crt -CAkey pki/ca.key -CAcreateserial -days 825 \
    -extfile pki/www.ext -out pki/www.crt 2>/dev/null
  rm -f pki/www.csr pki/www.ext pki/ca.srl
  chmod 600 pki/*.key
  [ -s pki/www.crt ] || { echo "[gen-secrets] ERROR: certificate generation failed"; rm -rf pki; exit 1; }
  echo "[gen-secrets] pki/ created: RAM+ Lab Root CA + certificate for www.dc.lab"
fi
